import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.DfDAiEgj.js";const f=JSON.parse('{"title":"同理心","description":"","frontmatter":{},"headers":[],"relativePath":"idea/empathy.md","filePath":"idea/empathy.md","lastUpdated":null}'),h={name:"idea/empathy.md"};function i(l,a,n,d,p,s){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="同理心" tabindex="-1">同理心 <a class="header-anchor" href="#同理心" aria-label="Permalink to &quot;同理心&quot;">​</a></h1><h2 id="「小白理论」" tabindex="-1">「小白理论」 <a class="header-anchor" href="#「小白理论」" aria-label="Permalink to &quot;「小白理论」&quot;">​</a></h2><p>在看待产品的时候，不能以我们创造者的专业身份来看，而需要用同理心，将自己转变为一个产品的典型用户，才能准确挖掘到用户心底最真实的诉求。</p><p>乔布斯只需要 1 秒钟就能变成「白痴」，这是他最厉害的地方，马化腾大概需要 5 秒，而小龙自己差不多需要 10 秒钟。</p><h3 id="海量用户时的tradeoff" tabindex="-1">海量用户时的Tradeoff <a class="header-anchor" href="#海量用户时的tradeoff" aria-label="Permalink to &quot;海量用户时的Tradeoff&quot;">​</a></h3><p>面对一个海量用户产品的时候，产品经理必须是一部分人的「白痴」，同时又是另一部分人「最精明的保护者」。</p><h2 id="理解愉悦与不爽" tabindex="-1">理解愉悦与不爽 <a class="header-anchor" href="#理解愉悦与不爽" aria-label="Permalink to &quot;理解愉悦与不爽&quot;">​</a></h2><p>生物性情绪：愉悦、不爽、愤怒、恐惧。刻度词：满足。愉悦就是被满足。崩了很久的需求被满足-爽。你吸收谁的营养，你就变成谁，你靠什么满足你，你就会成为它的样子，什么东西持续满足你，什么东西永远让你不爽，这就是你的命运。<a href="https://zhuanlan.zhihu.com/p/390605099" target="_blank" rel="noreferrer">2</a></p><h2 id="顺应用户潜意识" tabindex="-1">顺应用户潜意识 <a class="header-anchor" href="#顺应用户潜意识" aria-label="Permalink to &quot;顺应用户潜意识&quot;">​</a></h2><p>人会基于自身所处的角色，所在的场景和个人的认知判断，选择性的说一些他觉得正确的话。但是不代表是这个用户真实的选择。</p><p>销售-攻击防御，产品经理-不要让用户启动防御。</p><h2 id="警惕集体人格的误导" tabindex="-1">警惕集体人格的误导 <a class="header-anchor" href="#警惕集体人格的误导" aria-label="Permalink to &quot;警惕集体人格的误导&quot;">​</a></h2><p>教育是反人性的。要做到自然，自然和角色化是相反的词。集体是角色的聚集，好的产品经理是通过去角色化来研究真实的用户，而不是用应该来臆测。</p><h2 id="心理测试" tabindex="-1">心理测试 <a class="header-anchor" href="#心理测试" aria-label="Permalink to &quot;心理测试&quot;">​</a></h2><p>观察用户不起眼的微小动作，喜欢揣测他人的动机，并验证自己是否猜对了，养成这样的习惯，可以提高自己对用户心理诉求的敏锐度。</p>',15)])])}const u=e(h,[["render",i]]);export{f as __pageData,u as default};
